#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-19

# sandbox-probe.sh - Detect whether Claude Code's Bash sandbox is in force
#                    around THIS shell, using paired denial/control probes.
#
# Issue: #3322
#
# WHY PAIRED PROBES, NOT AN ANCESTRY WALK
# ---------------------------------------
# Claude Code applies its Bash sandbox as a Seatbelt profile IN-PROCESS to the
# shell it spawns (the profile is applied inside the child before exec). It does
# NOT wrap the command in `sandbox-exec`, so `sandbox-exec` never appears in the
# process tree and `ps`/`pgrep` ancestry cannot see it. Measured on CC 2.1.234 /
# macOS: an ancestry walk reports "no sandbox" inside a shell that is
# demonstrably confined.
#
# The only reliable signal is behavioural: run a probe that the sandbox policy
# DENIES next to a matched CONTROL that the policy ALLOWS, in the SAME shell.
# A denial with a passing control is evidence; a denial alone is not (it could
# be a missing file, a missing binary, or no network).
#
# WHAT THIS SCRIPT CAN AND CANNOT SEE
# -----------------------------------
#   * kernel EPERM from the Seatbelt profile  -> VISIBLE. Surfaces as
#     "Operation not permitted" on read/write, exit 127 on exec (exec EPERM),
#     or curl exit 56 / HTTP 000 on a blocked host. This is what we classify.
#   * a CC permission PROMPT (allow/ask/deny rules) -> NOT VISIBLE HERE. The
#     prompt is resolved by CC before the shell is spawned; a denied Bash call
#     surfaces to the model as CC's own refusal text, not as an errno from a
#     running shell, so this script never executes in that case.
#   * a PreToolUse HOOK block -> NOT VISIBLE HERE either. The hook decides
#     before spawn and returns its own message; this script never executes.
# So: every DENIED-sandbox row below is a kernel EPERM observed from inside an
# already-running shell. It cannot be confused with the other two layers.
#
# EXIT CODES
#   0  verdict printed (SANDBOX IN FORCE *or* NOT DETECTED - both are valid)
#   2  INSTRUMENT-INVALID: a control that must always pass did not, so no
#      verdict can be trusted. Never exits 0 having printed nothing.
#
# SAFETY
#   Credential-class files are read to /dev/null and never echoed. No `env` /
#   `printenv` value dumps. Safe to run in a public repo / on CI where no
#   sandbox exists: an all-ALLOWED result is reported as NOT DETECTED, exit 0.
#
# Usage: bash tests/security/sandbox-probe.sh
#        (no arguments; run it inside the shell you want to characterise)

# SC2016: several probe LABELS are literal display strings ('touch $HOME/<probe>',
# 'touch $TMPDIR (control)'). They are printed verbatim on purpose and must not
# expand -- expanding them would print the real home path into the report.
# shellcheck disable=SC2016

set -euo pipefail

# ---------------------------------------------------------------- formatting
if [[ -t 1 ]]; then
    RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[0;33m'
    BOLD=$'\033[1m'; NC=$'\033[0m'
else
    RED=''; GREEN=''; YELLOW=''; BOLD=''; NC=''
fi

DENIED_COUNT=0
ALLOWED_COUNT=0
SKIPPED_COUNT=0
DENIED_LAYERS=0
DENIED_LAYER_NAMES=()

row() { # row <layer> <probe> <verdict> [detail]
    local color=''
    case "$3" in
        DENIED-sandbox) color="$RED" ;;
        ALLOWED)        color="$GREEN" ;;
        SKIPPED)        color="$YELLOW" ;;
    esac
    printf '  %-10s %-26s %s%-15s%s %s\n' "$1" "$2" "$color" "$3" "$NC" "${4:-}"
}

tally() {
    case "$1" in
        DENIED-sandbox) DENIED_COUNT=$((DENIED_COUNT + 1)) ;;
        ALLOWED)        ALLOWED_COUNT=$((ALLOWED_COUNT + 1)) ;;
        SKIPPED)        SKIPPED_COUNT=$((SKIPPED_COUNT + 1)) ;;
    esac
}

mark_layer_denied() {
    DENIED_LAYERS=$((DENIED_LAYERS + 1))
    DENIED_LAYER_NAMES+=("$1")
}

# A control that must ALWAYS pass has failed -> the instrument is invalid and
# no verdict below it means anything. Named failure, exit 2. Never exit 0 here.
instrument_invalid() { # instrument_invalid <control-name> <detail>
    echo ""
    echo "${BOLD}${RED}INSTRUMENT-INVALID${NC}: control '$1' failed."
    echo "  detail: $2"
    echo "  A control that must pass in EVERY environment (sandboxed or not) did"
    echo "  not. Denial probes cannot be interpreted; no verdict is emitted."
    echo ""
    exit 2
}

# Run a probe, capturing BOTH its exit code and its combined output without
# letting a non-zero exit abort the script. `set -e` stays on for the
# surrounding logic, so every probe goes through this helper.
PROBE_RC=0
PROBE_OUT=''
probe_run() { # probe_run <cmd> [args...]
    PROBE_RC=0
    PROBE_OUT=''
    PROBE_OUT="$("$@" 2>&1)" || PROBE_RC=$?
    return 0
}

# Does the captured output/exit code match a known Seatbelt denial signature?
looks_denied() { # looks_denied <rc> <output>
    local rc="$1" out="$2" lower
    lower="$(printf '%s' "$out" | tr '[:upper:]' '[:lower:]')"
    [[ "$lower" == *"operation not permitted"* ]] && return 0
    [[ "$lower" == *"not permitted"* ]] && return 0
    [[ "$lower" == *"permissionerror"* ]] && return 0
    # exec EPERM under Seatbelt surfaces as 126/127 from the shell. Callers must
    # confirm the binary EXISTS first, otherwise 127 is just "not found".
    [[ "$rc" == "126" || "$rc" == "127" ]] && return 0
    return 1
}

echo ""
echo "${BOLD}Claude Code Bash sandbox probe${NC} (paired denial/control, issue #3322)"
echo "==========================================================================="
echo "  detection = paired denial probes, NOT a sandbox-exec ancestry walk"
echo ""
printf '  %-10s %-26s %-15s %s\n' "LAYER" "PROBE" "RESULT" "DETAIL"
printf '  %-10s %-26s %-15s %s\n' "-----" "-----" "------" "------"

# ------------------------------------------------------- 0. sanity control
# echo must work. If it does not, nothing below can be believed.
probe_run echo "sandbox-probe-alive"
if [[ "$PROBE_RC" -ne 0 || "$PROBE_OUT" != "sandbox-probe-alive" ]]; then
    instrument_invalid "echo" "rc=$PROBE_RC"
fi

# --------------------------------------------------- (a) process introspection
if command -v ps >/dev/null 2>&1; then
    probe_run ps -o comm= -p "$$"
    if looks_denied "$PROBE_RC" "$PROBE_OUT"; then
        row "process" 'ps -o comm= -p $$' "DENIED-sandbox" "exec EPERM (rc=$PROBE_RC)"
        tally DENIED-sandbox
        mark_layer_denied "process"
    else
        row "process" 'ps -o comm= -p $$' "ALLOWED" "rc=$PROBE_RC"
        tally ALLOWED
    fi
else
    row "process" 'ps -o comm= -p $$' "SKIPPED" "ps not installed"
    tally SKIPPED
fi

# control: id -un must always work (never sandbox-denied, no external deps)
probe_run id -un
if [[ "$PROBE_RC" -ne 0 || -z "$PROBE_OUT" ]]; then
    instrument_invalid "id -un" "rc=$PROBE_RC"
fi
row "process" "id -un (control)" "ALLOWED" "rc=0"
tally ALLOWED

# ------------------------------------------------------------- (b) network
NET_CONTROL_OK=0
if command -v curl >/dev/null 2>&1; then
    # control FIRST: an allowed host. If this fails we cannot tell a sandbox
    # denial from "this machine has no network" (normal on air-gapped CI), so
    # the whole network layer is SKIPPED rather than treated as invalid --
    # network reachability is NOT a must-always-pass control.
    probe_run curl -sS -o /dev/null --max-time 8 -w '%{http_code}' https://api.github.com
    NET_CONTROL_RC="$PROBE_RC"
    NET_CONTROL_CODE="$PROBE_OUT"
    if [[ "$NET_CONTROL_RC" -eq 0 && "$NET_CONTROL_CODE" =~ ^[23] ]]; then
        NET_CONTROL_OK=1
        row "network" "curl api.github.com (ctl)" "ALLOWED" "HTTP $NET_CONTROL_CODE"
        tally ALLOWED
    else
        row "network" "curl api.github.com (ctl)" "SKIPPED" "no egress here (rc=$NET_CONTROL_RC)"
        tally SKIPPED
    fi

    if [[ "$NET_CONTROL_OK" -eq 1 ]]; then
        probe_run curl -sS -o /dev/null --max-time 8 -w '%{http_code}' https://pastebin.com/
        # CC/Seatbelt network denial signature: CURLE_RECV_ERROR (56) or a
        # connect-class failure (7 / 35) with HTTP 000, while the control above
        # returned 2xx from the same shell.
        if [[ "$PROBE_RC" -eq 56 || "$PROBE_RC" -eq 7 || "$PROBE_RC" -eq 35 || "$PROBE_OUT" == *"000"* ]]; then
            row "network" "curl pastebin.com" "DENIED-sandbox" "rc=$PROBE_RC code=${PROBE_OUT//$'\n'/ }"
            tally DENIED-sandbox
            mark_layer_denied "network"
        elif [[ "$PROBE_RC" -eq 0 ]]; then
            row "network" "curl pastebin.com" "ALLOWED" "HTTP $PROBE_OUT"
            tally ALLOWED
        else
            row "network" "curl pastebin.com" "SKIPPED" "inconclusive rc=$PROBE_RC"
            tally SKIPPED
        fi
    else
        row "network" "curl pastebin.com" "SKIPPED" "control did not pass"
        tally SKIPPED
    fi
else
    row "network" "curl api.github.com (ctl)" "SKIPPED" "curl not installed"
    tally SKIPPED
    row "network" "curl pastebin.com" "SKIPPED" "curl not installed"
    tally SKIPPED
fi

# ------------------------------------------------------- (c) filesystem read
# Pick a credential-class path THAT EXISTS. An ENOENT is NOT a denial, so a
# missing file must be reported as SKIPPED, never counted as sandbox evidence.
#
# ⚠️ Do NOT use `[[ -e "$path" ]]` for the precondition. Measured on CC 2.1.234:
# the sandbox denies stat/traversal of ~/.ssh outright, so `-e` returns FALSE
# for a file that exists -- the test cannot distinguish EPERM from ENOENT and
# collapses a real denial into "nothing to probe". Use stat and read its stderr:
#   rc=0                        -> exists, run the read probe
#   stderr "not permitted"      -> kernel EPERM on stat = a genuine denial
#   anything else (ENOENT)      -> try the next candidate
CRED_PATH=''
CRED_STAT_DENIED=''
for candidate in "$HOME/.ssh/known_hosts" "$HOME/.netrc" "$HOME/.npmrc"; do
    STAT_RC=0
    STAT_ERR="$(stat "$candidate" 2>&1 >/dev/null)" || STAT_RC=$?
    if [[ "$STAT_RC" -eq 0 ]]; then
        CRED_PATH="$candidate"
        break
    fi
    if looks_denied "$STAT_RC" "$STAT_ERR"; then
        CRED_STAT_DENIED="$candidate"
        break
    fi
done

if [[ -n "$CRED_STAT_DENIED" ]]; then
    row "fs-read" "read credential file" "DENIED-sandbox" "EPERM on stat ${CRED_STAT_DENIED##*/}"
    tally DENIED-sandbox
    mark_layer_denied "fs-read"
elif [[ -n "$CRED_PATH" ]]; then
    # Contents go to /dev/null; only stderr is captured, and only its errno
    # class is ever reported. File contents are never printed.
    CRED_RC=0
    CRED_ERR="$(cat "$CRED_PATH" 2>&1 >/dev/null)" || CRED_RC=$?
    if looks_denied "$CRED_RC" "$CRED_ERR"; then
        row "fs-read" "read credential file" "DENIED-sandbox" "EPERM on ${CRED_PATH##*/}"
        tally DENIED-sandbox
        mark_layer_denied "fs-read"
    elif [[ "$CRED_RC" -eq 0 ]]; then
        row "fs-read" "read credential file" "ALLOWED" "readable: ${CRED_PATH##*/}"
        tally ALLOWED
    else
        row "fs-read" "read credential file" "SKIPPED" "inconclusive rc=$CRED_RC"
        tally SKIPPED
    fi
    unset CRED_ERR
else
    row "fs-read" "read credential file" "SKIPPED" "none of ~/.ssh/known_hosts, ~/.netrc, ~/.npmrc exist"
    tally SKIPPED
fi

# control: this script itself is readable in every environment
SELF="${BASH_SOURCE[0]}"
probe_run head -c 2 "$SELF"
if [[ "$PROBE_RC" -ne 0 ]]; then
    instrument_invalid "read own script" "rc=$PROBE_RC path=$SELF"
fi
row "fs-read" "read own script (control)" "ALLOWED" "rc=0"
tally ALLOWED

# ------------------------------------------------------ (d) filesystem write
HOME_TARGET="$HOME/.ork-sandbox-probe.$$"
probe_run touch "$HOME_TARGET"
if looks_denied "$PROBE_RC" "$PROBE_OUT"; then
    row "fs-write" 'touch $HOME/<probe>' "DENIED-sandbox" "EPERM (rc=$PROBE_RC)"
    tally DENIED-sandbox
    mark_layer_denied "fs-write"
elif [[ "$PROBE_RC" -eq 0 ]]; then
    row "fs-write" 'touch $HOME/<probe>' "ALLOWED" "rc=0"
    tally ALLOWED
    # silent: post-cleanup — probe artifact only; a failed unlink changes no verdict
    rm -f "$HOME_TARGET" 2>/dev/null || true
else
    row "fs-write" 'touch $HOME/<probe>' "SKIPPED" "inconclusive rc=$PROBE_RC"
    tally SKIPPED
fi

# control: a write under $TMPDIR must succeed everywhere, sandbox or not
TMP_ROOT="${TMPDIR:-/tmp}"
TMP_TARGET="${TMP_ROOT%/}/.ork-sandbox-probe.$$"
probe_run touch "$TMP_TARGET"
if [[ "$PROBE_RC" -ne 0 ]]; then
    instrument_invalid 'touch $TMPDIR' "rc=$PROBE_RC root=$TMP_ROOT"
fi
# silent: post-cleanup — probe artifact only; a failed unlink changes no verdict
rm -f "$TMP_TARGET" 2>/dev/null || true
row "fs-write" 'touch $TMPDIR (control)' "ALLOWED" "rc=0"
tally ALLOWED

# ------------------------------------------ (e) excludedCommands carve-out
# These binaries are carved out of the sandbox by CC's excludedCommands, so in
# a sandboxed shell they should STILL run. A denial here means the carve-out is
# not applying, which is itself sandbox evidence.
CARVE_DENIED=0
carve_probe() { # carve_probe <label> <cmd> [args...]
    local label="$1"
    shift
    if ! command -v "$1" >/dev/null 2>&1; then
        row "carve-out" "$label" "SKIPPED" "not installed"
        tally SKIPPED
        return 0
    fi
    probe_run "$@"
    if looks_denied "$PROBE_RC" "$PROBE_OUT"; then
        row "carve-out" "$label" "DENIED-sandbox" "carve-out not applying (rc=$PROBE_RC)"
        tally DENIED-sandbox
        CARVE_DENIED=1
    else
        row "carve-out" "$label" "ALLOWED" "rc=$PROBE_RC"
        tally ALLOWED
    fi
}

carve_probe "op --version" op --version
carve_probe "docker --version" docker --version
carve_probe "ssh -V" ssh -V

if [[ "$CARVE_DENIED" -eq 1 ]]; then
    mark_layer_denied "carve-out"
fi

# ------------------------------------------------------------------ verdict
LAYER_LIST=''
if [[ "${#DENIED_LAYER_NAMES[@]}" -gt 0 ]]; then
    LAYER_LIST=" (${DENIED_LAYER_NAMES[*]})"
fi

echo ""
echo "${BOLD}Totals${NC}"
echo "  DENIED-sandbox : $DENIED_COUNT"
echo "  ALLOWED        : $ALLOWED_COUNT"
echo "  SKIPPED        : $SKIPPED_COUNT"
echo "  layers denied  : ${DENIED_LAYERS}${LAYER_LIST}"
echo ""

if [[ "$DENIED_LAYERS" -ge 2 ]]; then
    echo "${BOLD}${RED}VERDICT: SANDBOX IN FORCE${NC} - ${DENIED_LAYERS} independent layers denied while their controls passed."
else
    echo "${BOLD}${GREEN}VERDICT: SANDBOX NOT DETECTED${NC} (or carve-outs cover these paths) - fewer than 2 independent layers denied."
fi
echo ""
exit 0
